sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
async function handler({ api, event, helpers, imports }) {
  try {
    // Log incoming event payload
    console.log("Incoming payload:", event);

    // Extract IDs from the selected properties
    var selectedProperty = event.payload.value;
    var selectedPropertyArray = selectedProperty.map(e => e.id);

    // Log the extracted property array
    console.log("Extracted property array:", selectedPropertyArray);

    // Update the state with the selected properties
    await api.setState('selectedProperty', { "property": selectedPropertyArray });

    // Retrieve and log the updated state
    api.getState('selectedProperty', (state) => {
      console.log("Updated state using getState:", state);
    });

    // Direct state check (if synchronous)
    console.log("Updated state directly from api.state:", api.state?.selectedProperty);
  } catch (error) {
    console.error("Error in handler:", error);
  }
}
